// GenerateMinimalResourceModel returns a *ResourceModel populated only with
// the supplied id + timeouts; every other field is at its typed null (or its
// declared minimal_default). Used by resources that need to persist a
// partial state when Create / Read returns mid-flight.
func GenerateMinimalResourceModel(id types.String, timeout timeouts.Value) *ResourceModel {
	return &ResourceModel{
		AllowDeletion:             types.BoolNull(),
		ClientOptions:             types.ObjectNull(ClientOptionsAttrTypes()),
		ConsumerOffsetSyncOptions: types.ObjectNull(ConsumerOffsetSyncOptionsAttrTypes()),
		ID:                        id,
		Name:                      types.StringNull(),
		Reason:                    types.StringNull(),
		SchemaRegistrySyncOptions: types.ObjectNull(SchemaRegistrySyncOptionsAttrTypes()),
		SecuritySyncOptions:       types.ObjectNull(SecuritySyncOptionsAttrTypes()),
		ShadowRedpandaID:          types.StringNull(),
		SourceRedpandaID:          types.StringNull(),
		State:                     types.StringNull(),
		Timeouts:                  timeout,
		TopicMetadataSyncOptions:  types.ObjectNull(TopicMetadataSyncOptionsAttrTypes()),
	}
}
